285	function Get-NormalizedHash([string]$Path, [string]$Stage) {
286	    $text = [IO.File]::ReadAllText($Path)
287	    switch ($Stage) {
288	        "spec" {
289	            $text = [regex]::Replace(
290	                $text, "(?m)^Spec-Review-Status:[^\r\n]*(\r?)$", 'Spec-Review-Status: Pending$1')
291	        }
292	        "impl" {
293	            $text = [regex]::Replace(
294	                $text, "(?m)^Impl-Review-Status:[^\r\n]*(\r?)$", 'Impl-Review-Status: Pending$1')
295	        }
296	        "task" {
297	            $text = [regex]::Replace(
298	                $text, "(?m)^Task-Review-Status:[^\r\n]*(\r?)$", 'Task-Review-Status: Pending$1')
299	            $text = [regex]::Replace(
300	                $text, "(?m)^Approval:[^\r\n]*(\r?)$", 'Approval: Draft$1')
301	            $text = [regex]::Replace(
302	                $text, "(?m)^Status:[^\r\n]*(\r?)$", 'Status: Planned$1')
303	                $text = [regex]::Replace(
304	                    $text, "(?m)^Second Approval:[^\r\n]*\r?\n?", '')
305	        }
306	    }
307	    $bytes = [Text.UTF8Encoding]::new($false).GetBytes($text)
308	    $sha = [Security.Cryptography.SHA256]::Create()
309	    # PS5.1-safe (no [Convert]::ToHexString, .NET 5+ only).
310	    try { return [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "").ToLowerInvariant() }
311	    finally { $sha.Dispose() }
312	}
313	function Get-RereviewNormalizedHash([string]$Path, [string]$Status) {
314	    $text = [IO.File]::ReadAllText($Path)
315	    $text = [regex]::Replace($text, "(?m)^Task-Review-Status:[^\r\n]*(\r?)$", 'Task-Review-Status: Passed$1')
316	    $text = [regex]::Replace($text, "(?m)^Approval:[^\r\n]*(\r?)$", 'Approval: Approved$1')
317	    $text = [regex]::Replace($text, "(?m)^Status:[^\r\n]*(\r?)$", "Status: ${Status}`$1")
318	    $text = [regex]::Replace($text, "(?m)^Second Approval:[^\r\n]*\r?\n?", '')
319	    $bytes = [Text.UTF8Encoding]::new($false).GetBytes($text)
320	    $sha = [Security.Cryptography.SHA256]::Create()
321	    try { return [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "").ToLowerInvariant() }
322	    finally { $sha.Dispose() }
323	}
324	# Twin of traceability_normalized_hash() in check-workflow-state.sh. Rewrites
325	# only each REQ row's final delivery-status cell, and only over the closed
326	# lifecycle vocabulary; every other byte still participates in the digest.
327	# [^\S\r\n] is horizontal whitespace only, so the explicit (\r?)$ keeps CRLF
328	# input byte-identical -- matching the convention of the functions above.
329	function Get-TraceabilityNormalizedHash([string]$Path) {
330	    $text = [IO.File]::ReadAllText($Path)
331	    $text = [regex]::Replace(
332	        $text,
333	        '(?m)^(\|[^\S\r\n]*REQ-.*\|)([^\S\r\n]*)(Planned|In Progress|Implementation Complete|Done|Blocked)([^\S\r\n]*\|[^\S\r\n]*)(\r?)$',
334	        '${1}${2}Planned${4}${5}')
335	    $bytes = [Text.UTF8Encoding]::new($false).GetBytes($text)
336	    $sha = [Security.Cryptography.SHA256]::Create()
337	    try { return [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "").ToLowerInvariant() }
338	    finally { $sha.Dispose() }
339	}
340	function Test-TraceabilityHash([string]$Candidate, [string]$Raw, [string]$Normalized) {
341	    if ([string]::IsNullOrEmpty($Candidate)) { return $false }
342	    return ($Candidate -eq $Raw -or $Candidate -eq $Normalized)
343	}
344	function Get-Header([string]$Path, [string]$Header) {
345	    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return "" }
346	    $match = [regex]::Match([IO.File]::ReadAllText($Path), "(?m)^$([regex]::Escape($Header)):\s*(\S+)")
347	    if ($match.Success) { return $match.Groups[1].Value.TrimEnd("`r") }
348	    return ""
349	}
350	function Test-ManifestPathRooted([string]$Path) {
351	    return [IO.Path]::IsPathRooted($Path) -or $Path -match "^[A-Za-z]:[\\/]"
352	}
353	function Get-RepositoryRelativePath(
354	    [string]$Path, [string]$RepositoryRoot, [string]$RecordedRoot = ""
355	) {
356	    $normalizedPath = $Path.Replace("\", "/")
357	    $normalizedRoot = $RepositoryRoot.Replace("\", "/").TrimEnd("/")
358	    $roots = @($normalizedRoot)
359	    if ($normalizedRoot.StartsWith("/private/var/")) {
360	        $roots += "/var/" + $normalizedRoot.Substring("/private/var/".Length)
361	    } elseif ($normalizedRoot.StartsWith("/var/")) {
362	        $roots += "/private/var/" + $normalizedRoot.Substring("/var/".Length)
363	    }
364	    if (-not (Test-ManifestPathRooted $Path)) { return $normalizedPath }
365	    foreach ($root in $roots) {
366	        if ($normalizedPath.StartsWith("$root/", [StringComparison]::OrdinalIgnoreCase)) {
367	            return $normalizedPath.Substring($root.Length + 1)
368	        }
369	    }
370	    if ($RecordedRoot) {
371	        $normalizedRecordedRoot = $RecordedRoot.Replace("\", "/").TrimEnd("/")
372	        if ($normalizedPath.StartsWith("$normalizedRecordedRoot/", [StringComparison]::Ordinal)) {
373	            return $normalizedPath.Substring($normalizedRecordedRoot.Length + 1)
374	        }
375	    }
376	    return $null
377	}
378	function Get-CandidateRootsForPath([string]$NormalizedPath) {
379	    # One recorded manifest path's candidate repository roots: split on the
380	    # repository's structural top-level directories, counting a split only
381	    # when the suffix it produces matches a canonical manifest shape (the
382	    # rationale is documented in Get-RecordedRepositoryRoot, whose per-path
383	    # inner derivation this extracts). Returned with the comma operator so
384	    # PowerShell hands back the HashSet itself instead of unrolling it.
385	    $candidateRoots = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
386	    foreach ($marker in @("/specs/", "/reports/", "/plugins/")) {
387	        $index = $NormalizedPath.IndexOf($marker, [StringComparison]::Ordinal)
388	        while ($index -ge 0) {
389	            $suffix = $NormalizedPath.Substring($index + 1)
390	            if ($suffix -cmatch '^specs/[a-z0-9][a-z0-9-]*/[^/]+$' -or
391	                $suffix -cmatch '^reports/(spec|impl|task)-review/[a-z0-9][a-z0-9-]*/attempt-[1-9][0-9]*/round-[1-9][0-9]*/[^/]+$' -or
392	                $suffix -cmatch '^plugins/[a-z0-9][a-z0-9-]*/references/[^/]+$') {
393	                [void]$candidateRoots.Add($NormalizedPath.Substring(0, $index))
394	            }
395	            $index = $NormalizedPath.IndexOf($marker, $index + 1, [StringComparison]::Ordinal)
396	        }
397	    }
398	    return ,$candidateRoots
399	}
400	function Get-RecordedRepositoryRoot($Contract, [string]$RepositoryRoot) {
401	    $normalizedRoot = $RepositoryRoot.Replace("\", "/").TrimEnd("/")
402	    $currentRoots = @($normalizedRoot)
403	    if ($normalizedRoot.StartsWith("/private/var/")) {
404	        $currentRoots += "/var/" + $normalizedRoot.Substring("/private/var/".Length)
405	    } elseif ($normalizedRoot.StartsWith("/var/")) {
406	        $currentRoots += "/private/var/" + $normalizedRoot.Substring("/var/".Length)
407	    }
408	    # Recorded manifest paths are absolute paths from the clone that produced
409	    # the review evidence, whose directory name has no relation to this
410	    # checkout's (worktrees, CI fixtures, and renamed clones are all legal).
411	    # Split them on the repository's own structural top-level directories
412	    # instead: every canonical manifest path is repo-relative under specs/,
413	    # reports/, or plugins/. A split candidate only counts when the suffix it
414	    # produces matches one of the canonical manifest shapes, so a feature
415	    # slug that happens to be named "specs", "reports", or "plugins" cannot
416	    # be mistaken for the repository root; a path with no unambiguous split
417	    # is invalid. A wrong split cannot weaken tamper detection - the derived
418	    # relative path must still match the canonical allowlist, its recorded
419	    # sha256 must match the live file, and every manifest entry must agree
420	    # on a single recorded root.
421	    $recordedRoots = [Collections.Generic.HashSet[string]]::new(
422	        [StringComparer]::Ordinal)
423	    foreach ($reviewer in @($Contract.reviewers)) {
424	        foreach ($item in @($reviewer.allowed_input_manifest)) {
425	            $rawPath = [string]$item.path
426	            if (-not (Test-ManifestPathRooted $rawPath)) { continue }
427	            $normalizedPath = $rawPath.Replace("\", "/")
428	            $isCurrent = $false
429	            foreach ($root in $currentRoots) {
430	                if ($normalizedPath.StartsWith("$root/", [StringComparison]::OrdinalIgnoreCase)) {
431	                    $isCurrent = $true
432	                    break
433	                }
434	            }
435	            if ($isCurrent) { continue }
436	            $candidateRoots = Get-CandidateRootsForPath $normalizedPath
437	            if ($candidateRoots.Count -ne 1) {
438	                return [pscustomobject]@{ Valid=$false; Root="" }
439	            }
440	            [void]$recordedRoots.Add(@($candidateRoots)[0])
441	            if ($recordedRoots.Count -gt 1) {
442	                return [pscustomobject]@{ Valid=$false; Root="" }
443	            }
444	        }
445	    }
446	    $root = if ($recordedRoots.Count) { @($recordedRoots)[0] } else { "" }
447	    return [pscustomobject]@{ Valid=$true; Root=$root }
448	}
449	function Test-ManifestHash(
450	    $Contract, [string]$Suffix, [string]$Expected, [string]$RepositoryRoot
451	) {
452	    $recorded = Get-RecordedRepositoryRoot $Contract $RepositoryRoot
453	    if (-not $recorded.Valid) { return $false }
454	    $target = $Suffix.TrimStart("/")
455	    foreach ($reviewer in @($Contract.reviewers)) {
456	        $found = $false
457	        foreach ($item in @($reviewer.allowed_input_manifest)) {
458	            $path = Get-RepositoryRelativePath ([string]$item.path) $RepositoryRoot $recorded.Root
459	            if ($null -ne $path -and $path -ceq $target -and
460	                [string]$item.sha256 -eq $Expected) {
461	                $found = $true
462	                break
463	            }
464	        }
465	        if (-not $found) { return $false }
466	    }
467	    return @($Contract.reviewers).Count -gt 0
468	}
469	# Like Test-ManifestHash, but for a live file: accepts a manifest entry that
470	# matches either the file's current hash or (for plugins/ reference docs
471	# only) its content as of the commit that produced $Contract. This tolerates
472	# legitimate later edits to plugins/ reference docs without weakening the
473	# check for any other input.
474	function Test-ManifestHashForFile(
475	    $Contract, [string]$Suffix, [string]$FilePath, [string]$RepositoryRoot, [string]$EvidenceFile
476	) {
477	    $current = Get-Sha256 $FilePath
478	    if (Test-ManifestHash $Contract $Suffix $current $RepositoryRoot) { return $true }
479	    $trimmed = $Suffix.TrimStart("/")
480	    if ($trimmed -notlike "plugins/*") { return $false }
481	    # Same "not evaluable, not failed" rule Test-PluginsHashMatches already
482	    # applies: a fixture root with no git history at all (e.g. a release
483	    # artifact, or WFI-024's reference-doc-forged-no-git fixture) has
484	    # nothing to reconcile a stale plugins/ manifest hash against, so this
485	    # must be accepted rather than rejected. Without this check, any live
486	    # drift of a plugins/ reference doc this function guards
487	    # (spec-review-calibration.md, reviewer-calibration.md) fails closed
488	    # under no-git even though the identical drift on risk-gate-matrix.md is
489	    # correctly tolerated by Test-PluginsHashMatches -- the two functions
490	    # must agree on this class.
491	    if (-not (Test-PluginsGitHistoryAvailable)) { return $true }
492	    $pin = Get-PluginsPinCommit $EvidenceFile
493	    if (-not $pin) { return $false }
494	    $historical = Get-PluginsHashAtPin $pin $trimmed
495	    if (-not $historical) { return $false }
496	    return Test-ManifestHash $Contract $Suffix $historical $RepositoryRoot
497	}
498	# Reuses Get-RepositoryRelativePath -- the SAME resolution Test-ManifestHash
499	# uses, not a substring probe -- to answer a narrower question than
500	# Test-ManifestHash: ignoring sha256 entirely, was $Suffix ever recorded in
501	# this manifest at all, and if so, at what hash(es)? Returns every distinct
502	# recorded sha256 for the path. An empty result means no reviewer declared
503	# this path -- a genuine provenance gap. Exactly one result means every
504	# entry for this path agrees on a single hash, which is what lets a caller
505	# tell "the manifest already knows this input, just at stale bytes" apart
506	# from "the manifest never knew this input at all." More than one result
507	# (reviewers disagree with each other about this path) is deliberately left
508	# for the caller to treat as inconclusive -- that is not simple staleness.
509	function Get-ManifestRecordedHashesForPath($Contract, [string]$Suffix, [string]$RepositoryRoot) {
510	    # NOT ,@(...): the caller already wraps this call in @(...) to guard
511	    # against PowerShell's single-element-array unwrap on return (the same
512	    # class of bug as elsewhere in this codebase); double-guarding with a
513	    # leading comma HERE as well produces a worse bug in the opposite
514	    # direction -- a genuinely EMPTY result becomes a 1-element array
515	    # containing an empty array, so $hashes.Count reads as 1 (not 0) and
516	    # $hashes[0] is an array object, not $null. A plain @(...) return,
517	    # left for the caller's own @(...) to reconstruct, is correct for 0, 1,
518	    # and N elements alike (verified directly against PS7's actual
519	    # behavior, not assumed from the comma-operator convention used
520	    # elsewhere in this file for different call shapes).
521	    $recorded = Get-RecordedRepositoryRoot $Contract $RepositoryRoot
522	    if (-not $recorded.Valid) { return @() }
523	    $target = $Suffix.TrimStart("/")
524	    $hashes = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
525	    foreach ($reviewer in @($Contract.reviewers)) {
526	        foreach ($item in @($reviewer.allowed_input_manifest)) {
527	            $path = Get-RepositoryRelativePath ([string]$item.path) $RepositoryRoot $recorded.Root
528	            if ($null -ne $path -and $path -ceq $target) {
529	                [void]$hashes.Add([string]$item.sha256)
530	            }
531	        }
532	    }
533	    return @($hashes)
534	}
535	# A reviewed document's recorded hash legitimately takes either of two forms.
536	# An ordinary review runs while the stage's status field still reads `Pending`
537	# (impl-review-precheck enforces that), so the reviewers record the raw bytes
538	# and the post-review flip to `Passed` is absorbed by Get-NormalizedHash. A
539	# re-review of an already-passed feature (--provenance-rereview) necessarily
540	# runs while the field already reads `Passed` -- that mode refuses to start
541	# otherwise -- so the reviewers record the raw bytes of THAT state, which no
542	# normalization can reproduce. Accepting either form does not weaken
543	# provenance: both prove the reviewers read the document's current body, and
544	# an edit to the body still matches neither.
545	function Test-ReviewedHash([string]$FilePath, [string]$Stage, [string]$Candidate) {
546	    if ([string]::IsNullOrEmpty($Candidate)) { return $false }
547	    if ($Candidate -eq (Get-NormalizedHash $FilePath $Stage)) { return $true }
548	    if ($Candidate -eq (Get-Sha256 $FilePath)) { return $true }
549	    if ($Stage -eq "task") {
550	        # A task-stage re-review binds the raw bytes of an executable state;
551	        # the quality gate's later Done flips are lifecycle transitions, not
552	        # body edits, and are absorbed by the two re-review canonical forms
553	        # (mirrors the bash twin's rereview_normalized_hash).
554	        if ($Candidate -eq (Get-RereviewNormalizedHash $FilePath "Implementation Complete")) { return $true }
555	        if ($Candidate -eq (Get-RereviewNormalizedHash $FilePath "Done")) { return $true }
556	    }
557	    return $false
558	}
559	function Test-ManifestReviewedHash(
560	    $Contract, [string]$Suffix, [string]$FilePath, [string]$Stage, [string]$RepositoryRoot
561	) {
562	    if (Test-ManifestHash $Contract $Suffix (Get-NormalizedHash $FilePath $Stage) $RepositoryRoot) { return $true }
563	    if (Test-ManifestHash $Contract $Suffix (Get-Sha256 $FilePath) $RepositoryRoot) { return $true }
564	    if ($Stage -eq "task") {
565	        if (Test-ManifestHash $Contract $Suffix (Get-RereviewNormalizedHash $FilePath "Implementation Complete") $RepositoryRoot) { return $true }
566	        if (Test-ManifestHash $Contract $Suffix (Get-RereviewNormalizedHash $FilePath "Done") $RepositoryRoot) { return $true }
567	    }
568	    return $false
569	}
570	function Test-AllowedLayerSupersetPath(
571	    [string]$Path, [string]$Feature, [string]$Stage, [string]$RepositoryRoot, [string]$RecordedRoot
572	) {
573	    # Scoped to impl-review only (issue #71): impl reviewers may have
574	    # legitimately reviewed the four layer specs even when the round
575	    # contract predates recording them. Spec/task stages must still
576	    # match the contract exactly.
577	    if ($Stage -ne "impl") { return $false }
578	    $relative = Get-RepositoryRelativePath $Path $RepositoryRoot $RecordedRoot
579	    if ($null -eq $relative) { return $false }
580	    return $relative -in @(
581	        "specs/$Feature/ux-spec.md", "specs/$Feature/frontend-spec.md",
582	        "specs/$Feature/infra-spec.md", "specs/$Feature/security-spec.md"
583	    )
584	}
585	function Test-ManifestSuperset(
586	    $ReviewerManifest, $ContractManifest, [string]$Feature, [string]$Stage,
587	    [string]$RepositoryRoot, [string]$RecordedRoot
588	) {
589	    $contractKeys = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
590	    foreach ($item in @($ContractManifest)) {
591	        [void]$contractKeys.Add("$([string]$item.path)`t$([string]$item.sha256)")
592	    }
593	    $reviewerKeys = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
594	    foreach ($item in @($ReviewerManifest)) {
595	        [void]$reviewerKeys.Add("$([string]$item.path)`t$([string]$item.sha256)")
596	    }
597	    # The contract must never record an entry the reviewer manifest lacks.
598	    foreach ($key in $contractKeys) {
599	        if (-not $reviewerKeys.Contains($key)) { return $false }
600	    }
601	    # The reviewer manifest may only exceed the contract with the four
602	    # implementation layer specs; any other extra entry is a fail.
603	    foreach ($item in @($ReviewerManifest)) {
604	        $key = "$([string]$item.path)`t$([string]$item.sha256)"
605	        if (-not $contractKeys.Contains($key)) {
606	            if (-not (Test-AllowedLayerSupersetPath ([string]$item.path) $Feature $Stage $RepositoryRoot $RecordedRoot)) {
607	                return $false
608	            }
609	        }
610	    }
611	    return $true
612	}
613	function Test-ManifestPaths(
614	    $Contract, [string]$Feature, [string]$Stage, [int]$Attempt, [int]$Round,
615	    [string]$RepositoryRoot
616	) {
617	    $recorded = Get-RecordedRepositoryRoot $Contract $RepositoryRoot
618	    if (-not $recorded.Valid) { return $false }
619	    $attemptRoot = "reports/$Stage-review/$Feature/attempt-$Attempt"
620	    $roundRoot = "$attemptRoot/round-$Round"
621	    foreach ($reviewer in @($Contract.reviewers)) {
622	        $role = [string]$reviewer.role
623	        $allowed = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
624	        foreach ($path in @(
625	            "specs/$Feature/requirements.md",
626	            "specs/$Feature/acceptance-tests.md",
627	            "specs/$Feature/investigation.md",
628	            "$roundRoot/precheck-result.json"
629	        )) { [void]$allowed.Add($path) }
630	        if ($Stage -eq "spec") {
631	            [void]$allowed.Add("plugins/sdd-review-loop/references/spec-review-calibration.md")
632	        } else {
633	            [void]$allowed.Add("plugins/sdd-review-loop/references/reviewer-calibration.md")
634	        }
635	        if ($Stage -eq "impl") {
636	            foreach ($path in @(
637	                "specs/$Feature/design.md", "specs/$Feature/ux-spec.md",
638	                "specs/$Feature/frontend-spec.md", "specs/$Feature/infra-spec.md",
639	                "specs/$Feature/security-spec.md"
640	            )) { [void]$allowed.Add($path) }
641	        }
642	        if ($Stage -eq "task") {
643	            foreach ($path in @(
644	                "specs/$Feature/tasks.md", "specs/$Feature/traceability.md",
645	                "specs/$Feature/design.md",
646	                "specs/$Feature/ux-spec.md", "specs/$Feature/frontend-spec.md",
647	                "specs/$Feature/infra-spec.md", "specs/$Feature/security-spec.md"
648	            )) { [void]$allowed.Add($path) }
649	        }
650	        if ($role -eq "$Stage-reviewer-b") { [void]$allowed.Add("$roundRoot/integrated-summary.json") }
651	        if ($Stage -eq "impl" -and $role -eq "impl-reviewer-a" -and $Round -gt 1) {
652	            [void]$allowed.Add("$attemptRoot/round-$($Round - 1)/integrated-summary.json")
653	        }
654	        if ($Stage -eq "task" -and $role -eq "task-reviewer-a") {
655	            [void]$allowed.Add("$roundRoot/dependency-graph.json")
656	        }
657	        if ($Stage -eq "task" -and $role -eq "task-reviewer-b") {
658	            [void]$allowed.Add("plugins/sdd-quality-loop/references/risk-gate-matrix.md")
659	            [void]$allowed.Add("plugins/sdd-quality-loop/references/risk-classification-policy.md")
660	        }
